      "content": "//! WebSocket transport. Scheduling and task ownership live in hub.\n//! MCP over HTTP (Streamable HTTP) lives in mcp_http and reuses the same hub.\nmod hub;\nmod mcp_http;\n\nuse futures_util::{SinkExt, StreamExt};\nuse hub::{hub_loop, HubMsg};\nuse serde::{Deserialize, Serialize};\nuse serde_json::{json, Value};\nuse std::net::SocketAddr;\nuse tokio::{\n    net::{TcpListener, TcpStream},\n    sync::mpsc,\n};\nuse tokio_tungstenite::{accept_async, tungstenite::Message};\n\nconst DEFAULT_PORT: u16 = 9225;\n/// MCP over HTTP 的默认端口（可用 `BRIDGE_HTTP_PORT` 覆盖，设为 0 关闭）\nconst DEFAULT_HTTP_PORT: u16 = 9226;\n\n#[derive(Debug, Clone, PartialEq, Eq)]\nenum Role {\n    Extension,\n    Client,\n}\n\n#[derive(Debug, Clone, Default, Serialize, Deserialize)]\nstruct WireMessage {\n    #[serde(default, skip_serializing_if = \"Option::is_none\")]\n    id: Option<String>,\n    #[serde(rename = \"type\", default, skip_serializing_if = \"Option::is_none\")]\n    type_: Option<String>,\n    #[serde(default, skip_serializing_if = \"Option::is_none\")]\n    role: Option<String>,\n    #[serde(default, skip_serializing_if = \"Option::is_none\")]\n    name: Option<String>,\n    #[serde(default, skip_serializing_if = \"Option::is_none\")]\n    client_id: Option<String>,\n    #[serde(default, skip_serializing_if = \"Option::is_none\")]\n    method: Option<String>,\n    #[serde(default, skip_serializing_if = \"Option::is_none\")]\n    params: Option<Value>,\n    #[serde(default, skip_serializing_if = \"Option::is_none\")]\n    success: Option<bool>,\n    #[serde(default, skip_serializing_if = \"Option::is_none\")]\n    result: Option<Value>,\n    #[serde(default, skip_serializing_if = \"Option::is_none\")]\n    error: Option<String>,\n    #[serde(default, skip_serializing_if = \"Option::is_none\")]\n    timeout_ms: Option<u64>,\n    #[serde(default, skip_serializing_if = \"Option::is_none\")]\n    deadline_ms: Option<u64>,\n}\nimpl WireMessage {\n    fn ok(id: &str, result: Value) -> Self {\n        Self {\n            id: Some(id.into()),\n            success: Some(true),\n            result: Some(result),\n            ..Self::default()\n        }\n    }\n    fn err(id: &str, error: impl Into<String>) -> Self {\n        Self {\n            id: Some(id.into()),\n            success: Some(false),\n            error: Some(error.into()),\n            ..Self::default()\n        }\n    }\n    fn to_text(&self) -> Message {\n        Message::Text(\n            serde_json::to_string(self)\n                .expect(\"wire message serializes\")\n                .into(),\n        )\n    }\n}\nasync fn handle_conn(\n    conn_id: u64,\n    stream: TcpStream,\n    addr: SocketAddr,\n    hub_tx: mpsc::UnboundedSender<HubMsg>,\n) {\n    let ws = match accept_async(stream).await {\n        Ok(ws) => ws,\n        Err(err) => {\n            eprintln!(\"[{addr}] websocket handshake failed: {err}\");\n            return;\n        }\n    };\n    let (mut ws_tx, mut ws_rx) = ws.split();\n    let (out_tx, mut out_rx) = mpsc::unbounded_channel::<Message>();\n\n    // 第一条消息必须是 hello\n    let hello = match ws_rx.next().await {\n        Some(Ok(Message::Text(text))) => match serde_json::from_str::<WireMessage>(&text) {\n            Ok(msg) => msg,\n            Err(err) => {\n                let _ = ws_tx\n                    .send(Message::Text(\n                        json!({ \"type\": \"error\", \"error\": format!(\"invalid hello: {err}\") })\n                            .to_string()\n                            .into(),\n                    ))\n                    .await;\n                return;\n            }\n        },\n        _ => {\n            let _ = ws_tx\n                .send(Message::Text(\n                    json!({ \"type\": \"error\", \"error\": \"expected hello message\" })\n                        .to_string()\n                        .into(),\n                ))\n                .await;\n            return;\n        }\n    };\n\n    let role = match hello.role.as_deref() {\n        Some(\"extension\") => Role::Extension,\n        Some(\"client\") => Role::Client,\n        _ => {\n            let _ = ws_tx\n                .send(Message::Text(\n                    json!({ \"type\": \"error\", \"error\": \"hello must declare role\" })\n                        .to_string()\n                        .into(),\n                ))\n                .await;\n            return;\n        }\n    };\n    let name = hello.name.clone().unwrap_or_else(|| \"unnamed\".to_string());\n    let client_id = hello.client_id.clone();\n    let _ = hub_tx.send(HubMsg::Register {\n        conn_id,\n        role,\n        name,\n        client_id,\n        tx: out_tx,\n    });\n\n    loop {\n        tokio::select! {\n            incoming = ws_rx.next() => {\n                match incoming {\n                    Some(Ok(Message::Text(text))) => {\n                        if let Ok(msg) = serde_json::from_str::<WireMessage>(&text) {\n                            let _ = hub_tx.send(HubMsg::Forward { conn_id, msg });\n                        }\n                    }\n                    Some(Ok(_)) => {}\n                    _ => break,\n                }\n            }\n            outgoing = out_rx.recv() => match outgoing {\n                Some(msg) => {\n                    if ws_tx.send(msg).await.is_err() {\n                        break;\n                    }\n                }\n                None => break,\n            },\n        }\n    }\n    let _ = hub_tx.send(HubMsg::Unregister { conn_id });\n}\n\n#[tokio::main]\nasync fn main() -> Result<(), Box<dyn std::error::Error>> {\n    let port = std::env::var(\"BRIDGE_PORT\")\n        .ok()\n        .and_then(|p| p.parse().ok())\n        .unwrap_or(DEFAULT_PORT);\n    let addr = format!(\"127.0.0.1:{port}\");\n    let listener = TcpListener::bind(&addr).await?;\n    let http_port = std::env::var(\"BRIDGE_HTTP_PORT\")\n        .ok()\n        .and_then(|p| p.parse().ok())\n        .unwrap_or(DEFAULT_HTTP_PORT);\n    let http_bind = std::env::var(\"BRIDGE_HTTP_BIND\").unwrap_or_else(|_| \"127.0.0.1\".into());\n    eprintln!(\"browser-bridge server listening on ws://{addr}\");\n    if http_port != 0 {\n        eprintln!(\"browser-bridge MCP over HTTP: http://{http_bind}:{http_port}/mcp\");\n    }\n\n    let (hub_tx, hub_rx) = mpsc::unbounded_channel();\n    tokio::spawn(hub_loop(hub_rx));\n\n    if http_port != 0 {\n        // 独立端口、独立 HTTP 栈：原有 WS 行为与协议不变。\n        match format!(\"{http_bind}:{http_port}\").parse::<SocketAddr>() {\n            Ok(http_addr) => {\n                let ws_url = format!(\"ws://127.0.0.1:{port}\");\n                tokio::spawn(async move { mcp_http::serve(http_addr, ws_url).await });\n            }\n            Err(error) => eprintln!(\n                \"invalid BRIDGE_HTTP_BIND/BRIDGE_HTTP_PORT: {error}; HTTP MCP disabled\"\n            ),\n        }\n    }\n\n    run_ws(listener, hub_tx).await?;\n    Ok(())\n}\n\nasync fn run_ws(\n    listener: TcpListener,\n    hub_tx: mpsc::UnboundedSender<HubMsg>,\n) -> Result<(), Box<dyn std::error::Error>> {\n    let mut next_id: u64 = 0;\n    loop {\n        let (stream, addr) = listener.accept().await?;\n        next_id += 1;\n        let hub_tx = hub_tx.clone();\n        tokio::spawn(async move { handle_conn(next_id, stream, addr, hub_tx).await });\n    }\n}\n"
